use poolster_core::native::rpc::RpcGenerationOptions;
pub(super) fn render(runtime: &str, options: &RpcGenerationOptions) -> Option<(String, String)> {
    if !options.emit_binary && !options.emit_json && !options.emit_reflection {
        return None;
    }
    let mut code = format!("# Generated by Poolster.\nimport {runtime} as _runtime\n");
    let mut types = String::from(
        "# Generated by Poolster.\nfrom typing import TypeVar, Mapping\nfrom google.protobuf.message import Message\n_T = TypeVar(\"_T\", bound=Message)\n",
    );
    if !options.representations.is_native() {
        let id = runtime.trim_start_matches("_poolster_rpc_");
        types = types.replace(
            "_T = TypeVar(\"_T\", bound=Message)",
            "_T = TypeVar(\"_T\")",
        );
        types.push_str(&format!(
            "from _poolster_values_{id} import ValueMessage as _ValueMessage\n"
        ));
    }
    if options.emit_binary {
        code.push_str(&format!(
            "\n_ENCODE_TYPES = {}\n_DECODE_TYPES = {}\n",
            serde_json::to_string(&options.encode_include_types).expect("type selection"),
            serde_json::to_string(&options.decode_include_types).expect("type selection")
        ));
        code.push_str("\ndef encode(value):\n    if hasattr(value, \"to_native\"): value = value.to_native()\n    if _ENCODE_TYPES and value.DESCRIPTOR.full_name not in _ENCODE_TYPES: raise ValueError(\"Message type excluded from encoder\")\n    return _runtime._encode(value)\n\ndef decode(cls, data):\n    target = getattr(cls, \"_native_type\", cls)\n    if _DECODE_TYPES and target.DESCRIPTOR.full_name not in _DECODE_TYPES: raise ValueError(\"Message type excluded from decoder\")\n    value = _runtime._decode(target, data)\n    return cls.from_native(value) if target is not cls else value\n");
        types.push_str(&format!("\ndef encode(value: {}) -> bytes: ...\ndef decode(cls: type[_T], data: bytes) -> _T: ...\n",if options.representations.is_native() {"Message"} else {"Message | _ValueMessage"}));
    }
    if options.emit_json {
        code.push_str(include_str!("json.py.tmpl"));
        types.push_str("\ndef to_json(value: Message, *, preserving_proto_field_name: bool = ..., use_integers_for_enums: bool = ..., always_print_fields_with_no_presence: bool = ...) -> str: ...\ndef from_json(cls: type[_T], text: str, *, ignore_unknown_fields: bool = ...) -> _T: ...\n");
    }
    if options.emit_reflection {
        code.push_str("\ndef message_type(full_name):\n    return _runtime.message(full_name)\n\ndef descriptors():\n    return _runtime._SET\n");
        types.push_str("\nfrom google.protobuf.descriptor_pb2 import FileDescriptorSet\ndef message_type(full_name: str) -> type[Message]: ...\ndef descriptors() -> FileDescriptorSet: ...\n");
    }
    if !options.representations.is_native() {
        types = types.replace(
            "def to_json(value: Message,",
            "def to_json(value: Message | _ValueMessage,",
        );
    }
    Some((code, types))
}
